 async function applyRecurring(){if(busy)return;setBusy(true);setRecurringNotice("");const now=new Date(),month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;const {data,error}=await supabase.rpc("apply_recurring_month",{p_month:month});if(error)setAuthError(error.message);else{setRecurringNotice(`${data??0} opération(s) enregistrée(s) pour ${month}. Aucun doublon possible.`);const res=await supabase.from("transactions").select("id,label,amount,type,category,created_at").order("created_at",{ascending:false});if(res.error)setAuthError(res.error.message);else setEntries((res.data??[]).map(v=>({id:v.id,label:v.label,amount:Number(v.amount),type:v.type,category:v.category,date:v.created_at}))) }setBusy(false)}
