 const analytics=useMemo(()=>{const [year,month]=analyticsMonth.split("-").map(Number);const selected=entries.filter(e=>{const d=new Date(e.date);return d.getFullYear()===year&&d.getMonth()+1===month});const previous=entries.filter(e=>{const d=new Date(e.date);return d.getFullYear()===new Date(year,month-2,1).getFullYear()&&d.getMonth()===new Date(year,month-2,1).getMonth()});const sum=(rows:Entry[],type:"income"|"expense")=>rows.filter(e=>e.type===type).reduce((n,e)=>n+e.amount,0);const income=sum(selected,"income"),expense=sum(selected,"expense"),previousExpense=sum(previous,"expense"),previousIncome=sum(previous,"income");const categories=Array.from(new Set(selected.filter(e=>e.type==="expense").map(e=>e.category))).map(name=>({name,value:selected.filter(e=>e.type==="expense"&&e.category===name).reduce((n,e)=>n+e.amount,0)})).sort((a,b)=>b.value-a.value);const trend=Array.from({length:analyticsRange},(_,i)=>{const d=new Date(year,month-analyticsRange+i,1);const rows=entries.filter(e=>{const t=new Date(e.date);return t.getFullYear()===d.getFullYear()&&t.getMonth()===d.getMonth()});return {key:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`,label:d.toLocaleDateString("fr-FR",{month:"short",year:"2-digit"}),income:sum(rows,"income"),expense:sum(rows,"expense")}});const savings=savingsMovements.filter(m=>m.occurred_on.slice(0,7)===analyticsMonth);const deposits=savings.filter(m=>m.kind!=="withdrawal").reduce((n,m)=>n+m.amount,0),withdrawals=savings.filter(m=>m.kind==="withdrawal").reduce((n,m)=>n+m.amount,0);return {income,expense,previousIncome,previousExpense,categories,trend,deposits,withdrawals,count:selected.length,net:income-expense}},[entries,savingsMovements,analyticsMonth,analyticsRange]);
