 const visibleEntries=useMemo(()=>entries.filter(e=>{const d=new Date(e.date);const date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;return (filterType==="all"||e.type===filterType)&&(filterCategory==="all"||e.category===filterCategory)&&(!filterFrom||date>=filterFrom)&&(!filterTo||date<=filterTo)&&(!filterMin||e.amount>=Number(filterMin))&&(!filterMax||e.amount<=Number(filterMax))&&(e.label+" "+e.category).toLowerCase().includes(search.toLowerCase().trim())}),[entries,filterType,filterCategory,filterFrom,filterTo,filterMin,filterMax,search]);
 function exportCsv(){const escape=(v:string)=>'"'+v.replaceAll('"','""')+'"';const lines=[["Date","Description","Type","Catégorie","Montant MAD"].join(";"),...entries.map(e=>[new Date(e.date).toLocaleDateString("fr-FR"),escape(e.label),e.type,escape(e.category),e.amount.toFixed(2)].join(";"))];const blob=new Blob(["\uFEFF"+lines.join("\r\n")],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="mizan-transactions.csv";a.click();URL.revokeObjectURL(url)}
